285	  async atualizarStatus(id: number, status: Status) {
286	    if (!STATUS_VALIDOS.includes(status)) {
287	      throw new BadRequestException(`Status inválido: ${status}`);
288	    }
289	
290	    const { data, error } = await this.supabase.client
291	      .from('orders')
292	      .update({ status, updated_at: new Date().toISOString() })
293	      .eq('id', id)
294	      .select('id, status, total, restaurant_id, updated_at')
295	      .single();
296	
297	    if (error) throw error;
298	    if (!data) throw new NotFoundException(`Pedido ${id} não encontrado`);
299	
300	    if (status === 'confirmed') {
301	      await this.rotearItensParaSetor(id, data.restaurant_id);
302	    }
303	
304	    // Comissão registrada automaticamente via trigger on_order_delivered quando status = 'delivered'
305	    return data;
