}

// KDS por setor (módulo Salão): tela genérica reaproveitável por impressora/setor
// (cozinha, bar, salgados...) — lista PLANA de itens (não agrupa por mesa/comanda,
// cada item tem sua própria ação de preparo/impressão), ordenada por chegada.
async getKdsSetor(restaurantId: number, impressoraId: number) {
  // Itens "pronto" de hoje inteiro também entram — sem isso, um clique errado em
  // "Entregue"/"Pronto" faz o item sumir da tela sem chance de desfazer. A tela
  // (Cozinha/Produção) que decide mostrar só os últimos N com opção de expandir.
  const inicioDoDia = new Date();
  inicioDoDia.setHours(0, 0, 0, 0);
  const limiteProntos = inicioDoDia.toISOString();
  const { data: itens, error } = await this.supabase.client
    .from('order_items')
    .select('id, quantity, unit_price, observacao, product_id, status, enviado_em, preparando_em, pronto_em, entregue_garcom, order_id, products(name), orders(id, restaurant_id, mesa_id, cliente_mesa_nome, garcom_id, customer_id, status, numero_comanda, is_venda_balcao, aberto_por_nome, motoboy_lat, motoboy_lng, delivery_occurrence, mesas(numero, nome), garcons(nome))')
    .eq('impressora_id', impressoraId)
    .or(`status.in.(enviado,preparando),and(status.eq.pronto,pronto_em.gte.${limiteProntos})`)
    .order('enviado_em', { ascending: true });
  if (error) throw error;

  const itensValidos = (itens as any[]).filter((i) => i.orders?.restaurant_id === restaurantId);

  // Um item roteado pra uma impressora/setor pode vir tanto de comanda do salão
  // (mesa_id/garcom_id preenchidos) quanto de pedido de delivery (produto com a
  // mesma impressora configurada) — resolve nome do cliente de delivery à parte
  // pra tela poder filtrar e exibir por canal.
  const customerIds = [...new Set(itensValidos.map((i) => i.orders?.customer_id).filter(Boolean))];
  const { data: customers } = customerIds.length
    ? await this.supabase.client.from('customers').select('id, name').in('id', customerIds)
    : { data: [] as any[] };
  const customerMap = Object.fromEntries((customers ?? []).map((c: any) => [c.id, c.name]));

  return {
    itens: itensValidos.map((i) => {
      const ehSalao = !!(i.orders?.mesa_id || i.orders?.garcom_id || i.orders?.cliente_mesa_nome);
      return {
        id: i.id,
        order_id: i.order_id,
        product_name: i.products?.name,
        quantity: i.quantity,
        observacao: i.observacao,
        status: i.status,
        enviado_em: i.enviado_em,
        preparando_em: i.preparando_em,
        pronto_em: i.pronto_em,
        entregue_garcom: i.entregue_garcom ?? false,
        tipo: ehSalao ? 'salao' : 'delivery',
        mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
        mesa_numero: i.orders?.mesas?.numero ?? null,
        numero_comanda: i.orders?.numero_comanda ?? null,
        cliente: i.orders?.cliente_mesa_nome ?? (i.orders?.customer_id ? customerMap[i.orders.customer_id] ?? null : null),
        garcom: i.orders?.garcons?.nome
          ?? (i.orders?.is_venda_balcao ? 'Balcão' : (ehSalao ? 'Sem Garçom - Venda Direta' : null)),
        venda_balcao: i.orders?.is_venda_balcao ?? false,
        // Status de entrega do pedido (delivery) — usado no Bar pra alerta de motoboy
        // (em trânsito/entregue/ocorrência) e botão de localizar no mapa.
        pedido_status: i.orders?.status ?? null,
        motoboy_lat: i.orders?.motoboy_lat ?? null,
        motoboy_lng: i.orders?.motoboy_lng ?? null,
        delivery_occurrence: i.orders?.delivery_occurrence ?? null,
      };
    }),
  };
}

// Move só esse item de "aguardando" (enviado) pra "preparando" — ação por item, não
// por comanda inteira (cada prato tem seu próprio ritmo de preparo).
async iniciarPreparoItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();
  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  const { error } = await this.supabase.client
    .from('order_items')
    .update({ status: 'preparando', preparando_em: new Date().toISOString() })
    .eq('id', itemId);
  if (error) throw error;

  return { ok: true };
}

async marcarItemPronto(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  const { error } = await this.supabase.client.from('order_items').update({ status: 'pronto', pronto_em: new Date().toISOString() }).eq('id', itemId);
  if (error) throw error;
  return { ok: true };
}

// Desfaz clique errado na Cozinha/Bar — volta um passo (pronto -> preparando ->
// enviado/aguardando). "Enviado" já é o início da fila do KDS, não dá pra voltar mais.
async voltarStatusItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  if (item.status === 'pronto') {
    const { error } = await this.supabase.client
      .from('order_items')
      .update({ status: 'preparando', pronto_em: null })
      .eq('id', itemId);
    if (error) throw error;
    return { ok: true, status: 'preparando' };
  }

  if (item.status === 'preparando') {
    const { error } = await this.supabase.client
      .from('order_items')
      .update({ status: 'enviado', preparando_em: null })
      .eq('id', itemId);
    if (error) throw error;
    return { ok: true, status: 'enviado' };
  }

  throw new BadRequestException('Item já está aguardando — não dá pra voltar mais');
}

// Cancela item ainda "Aguardando Preparo" — some da fila de Produção e Cozinha
// (ambas leem por status via GET /kds). Só permite nesse estágio: depois que a
// cozinha já começou o preparo, cancelar teria que envolver estorno/decisão do
// dono, fora do escopo desse botão rápido.
async cancelarItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  if (item.status !== 'enviado') {
    throw new BadRequestException('Só é possível cancelar um item enquanto está Aguardando Preparo');
  }

  const { error } = await this.supabase.client
    .from('order_items')
    .update({ status: 'cancelado', cancelado_em: new Date().toISOString() })
    .eq('id', itemId);
  if (error) throw error;

  return { ok: true };
}

